#include <iostream>
#include <algorithm>
#include <cstdio>
#include <cstring>
using namespace std;

int n, k, p;

int fast_power(int base, int exp) {
    int result = 1;
    int current = base;
    while (exp > 0) {
        if (exp & 1) result = (long long)result * current % p;
        current = (long long)current * current % p;
        exp >>= 1;
    }
    return result;
}

int get_lowbit(int x) {
    return x & (-x);
}

int f[26][250010];
int factorial[250010], inv_factorial[250010];

void initialize() {
    factorial[0] = 1;
    for (int i = 1; i <= n; ++i)
        factorial[i] = (long long)factorial[i - 1] * i % p;
    inv_factorial[n] = fast_power(factorial[n], p - 2);
    for (int i = n; i >= 1; --i)
        inv_factorial[i - 1] = (long long)inv_factorial[i] * i % p;
}

int compute(int current, int S) {
    if (f[current][S] != -1) return f[current][S];
    if (S == 0) {
        f[current][S] = factorial[n];
        for (int i = 1; i <= current; ++i)
            f[current][S] = (long long)f[current][S] * (k - i + 1) % p;
        return f[current][S];
    }
    f[current][S] = 0;
    int U = S - get_lowbit(S);
    for (int T = U; T; T = (T - 1) & U)
        f[current][S] = (f[current][S] + (long long)inv_factorial[S - T] * compute(current + 1, T)) % p;
    f[current][S] = (f[current][S] + (long long)inv_factorial[S] * compute(current + 1, 0)) % p;
    return f[current][S];
}

int main() {
    scanf("%d %d %d", &n, &k, &p);
    int answer = 1;
    for (int i = 1; i <= n; ++i)
        answer = (long long)answer * k % p;
    if (n % 2 == 0) {
        initialize();
        memset(f, -1, sizeof(f));
        answer = (answer - compute(0, n) + p) % p;
    }
    printf("%d\n", answer);
    return 0;
}
